// Structural changes outside setup (spec 0003 R0c, A3): opening an
// account or merging two categories, restated before it is applied,
// and always minted as the asking member's own role (ADR 0042's
// "acts_as") so a non-admin's attempt fails at the database, exactly
// like setup-conversation.json's own writes -- this workflow never
// checks the member's role itself, the grant does.
const crypto = require('crypto');
const http = require('http');
const { URL } = require('url');

const PG = 'http://postgrest:3000';

function b64url(buf) {
  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function mintToken(role, memberId) {
  const header = b64url(Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })));
  const payload = b64url(Buffer.from(JSON.stringify({ role, member_id: memberId, exp: Math.floor(Date.now() / 1000) + 60 })));
  const signingInput = `${header}.${payload}`;
  const signature = b64url(crypto.createHmac('sha256', $env.PGRST_JWT_SECRET).update(signingInput).digest());
  return `${signingInput}.${signature}`;
}

function httpJson(method, url, headers, body) {
  return new Promise((resolve, reject) => {
    const bodyStr = body !== undefined ? JSON.stringify(body) : undefined;
    const u = new URL(url);
    const options = {
      hostname: u.hostname, port: u.port, path: u.pathname + u.search, method,
      headers: Object.assign({ 'Content-Type': 'application/json' }, headers, bodyStr ? { 'Content-Length': Buffer.byteLength(bodyStr) } : {}),
    };
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => {
        let parsed = null;
        try { parsed = data ? JSON.parse(data) : null; } catch (e) { parsed = data; }
        resolve({ status: res.statusCode, body: parsed });
      });
    });
    req.on('error', reject);
    if (bodyStr) req.write(bodyStr);
    req.end();
  });
}

function parseIntent(text) {
  const lowered = text.toLowerCase();

  const mergeMatch = lowered.match(/merge\s+(?:the\s+)?['"]?([\w \-]+?)['"]?\s+(?:and|into|with)\s+['"]?([\w \-]+?)['"]?(?:\s+categor|\s*$)/i);
  if (mergeMatch) {
    return { action: 'merge_category', from_name: mergeMatch[1].trim(), into_name: mergeMatch[2].trim() };
  }
  if (/merge.*categor/i.test(lowered)) {
    return null;
  }

  const openMatch = text.match(/open (?:a |an |new )?['"]?([\w \-&]+?)['"]?\s+account/i);
  if (openMatch) {
    const name = openMatch[1].trim();
    const account_type = /credit card|card|loan|кредит/i.test(lowered) ? 'liability' : 'asset';
    return { action: 'open_account', account_name: name, account_type };
  }

  return null;
}

function restate(intent, isRu) {
  if (intent.action === 'open_account') {
    return isRu
      ? `Открыть счёт «${intent.account_name}» (${intent.account_type === 'liability' ? 'обязательство' : 'актив'})? Подтвердите.`
      : `Open a "${intent.account_name}" account (${intent.account_type})? Please confirm.`;
  }
  if (intent.action === 'merge_category') {
    return isRu
      ? `Объединить категорию «${intent.from_name}» в «${intent.into_name}»? Подтвердите.`
      : `Merge the "${intent.from_name}" category into "${intent.into_name}"? Please confirm.`;
  }
  return isRu ? 'Не понял запрос.' : "I didn't understand that request.";
}

const AFFIRMATIVE = /\b(yes|yep|yeah|correct|right|confirm|agreed|do it|да|верно|подтвержда)/i;
const NEGATIVE = /\b(no|nope|cancel|never ?mind|нет|отмен)/i;

async function main() {
  const item = $input.first().json;
  const { member_id, chat_id, message_thread_id, text, language_hint } = item;
  const isRu = language_hint === 'ru';

  const readToken = mintToken('hh_agent', member_id);
  const readAuth = { Authorization: `Bearer ${readToken}` };

  const memberRes = await httpJson('GET', `${PG}/member?id=eq.${member_id}&select=role`, readAuth);
  const role = (memberRes.body && memberRes.body[0] && memberRes.body[0].role) === 'admin' ? 'hh_admin' : 'hh_member';
  const actingToken = mintToken(role, member_id);
  const auth = { Authorization: `Bearer ${actingToken}` };

  const openRes = await httpJson('GET', `${PG}/conversation?member_id=eq.${member_id}&kind=eq.structural_change&closed_at=is.null`, readAuth);
  const conversation = (openRes.body || [])[0] || null;

  if (!conversation) {
    const intent = parseIntent(text);
    if (!intent) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Не понял запрос.' : "I didn't understand that request." } }];
    }
    await httpJson('POST', `${PG}/conversation`, Object.assign({ Prefer: 'return=minimal' }, readAuth), {
      member_id, kind: 'structural_change', step: 'confirm', payload: intent,
    });
    return [{ json: { chat_id, message_thread_id, text: restate(intent, isRu) } }];
  }

  const intent = conversation.payload;

  if (NEGATIVE.test(text) || !AFFIRMATIVE.test(text)) {
    await httpJson('PATCH', `${PG}/conversation?id=eq.${conversation.id}`, Object.assign({ Prefer: 'return=minimal' }, readAuth), { closed_at: new Date().toISOString() });
    return [{ json: { chat_id, message_thread_id, text: isRu ? 'Отменено.' : 'Cancelled.' } }];
  }

  // Applying the change runs as the asking member's own role (ADR
  // 0042 acts_as) -- a non-admin's confirmation fails right here at
  // the database, the same guarantee setup-conversation.json gives A4.
  let resultText;
  if (intent.action === 'open_account') {
    const created = await httpJson('POST', `${PG}/account`, Object.assign({ Prefer: 'return=representation' }, auth), {
      type: intent.account_type, name: intent.account_name,
    });
    if (created.status < 200 || created.status >= 300) {
      resultText = isRu ? 'Только администратор может добавлять счета.' : 'Only an admin can add accounts.';
    } else {
      resultText = isRu ? `Счёт «${intent.account_name}» открыт.` : `Opened "${intent.account_name}".`;
    }
  } else if (intent.action === 'merge_category') {
    const fromRes = await httpJson('GET', `${PG}/account?type=eq.expense&name=eq.${encodeURIComponent(intent.from_name)}&select=id`, auth);
    const intoRes = await httpJson('GET', `${PG}/account?type=eq.expense&name=eq.${encodeURIComponent(intent.into_name)}&select=id`, auth);
    const fromId = (fromRes.body || [])[0] && fromRes.body[0].id;
    const intoId = (intoRes.body || [])[0] && intoRes.body[0].id;
    if (!fromId || !intoId) {
      resultText = isRu ? 'Не нашёл одну из категорий.' : "I couldn't find one of those categories.";
    } else {
      const repointed = await httpJson('PATCH', `${PG}/posting?account_id=eq.${fromId}`, Object.assign({ Prefer: 'return=minimal' }, auth), { account_id: intoId });
      const deactivated = await httpJson('PATCH', `${PG}/account?id=eq.${fromId}`, Object.assign({ Prefer: 'return=minimal' }, auth), { active: false });
      if ((repointed.status >= 200 && repointed.status < 300) && (deactivated.status >= 200 && deactivated.status < 300)) {
        resultText = isRu ? 'Категории объединены.' : 'Categories merged.';
      } else {
        resultText = isRu ? 'Только администратор может объединять категории.' : 'Only an admin can merge categories.';
      }
    }
  } else {
    resultText = isRu ? 'Что-то пошло не так.' : 'Something went wrong.';
  }

  await httpJson('PATCH', `${PG}/conversation?id=eq.${conversation.id}`, Object.assign({ Prefer: 'return=minimal' }, readAuth), { closed_at: new Date().toISOString() });
  return [{ json: { chat_id, message_thread_id, text: resultText } }];
}

return main();
